insert into public.worlds (id, name, order_index, theme_color, description) values
  ('coin-cove', 'Coin Cove', 1, '#E8A33D', 'Where every quest begins — meet money, coins, and your first earnings.'),
  ('market-town', 'Market Town', 2, '#D13E19', 'Bustling stalls and smart choices: needs, wants, and clever shopping.'),
  ('golden-vault', 'Golden Vault', 3, '#0B5C50', 'Grow your savings and set goals in the safest vault around.'),
  ('sky-exchange', 'Sky Exchange', 4, '#367D99', 'Digital coins, cards, and currencies from across the world.'),
  ('guardian-gate', 'Guardian Gate', 5, '#5B4B8A', 'Stay sharp: spot scams, phishing, and stay safe online.'),
  ('horizon-peaks', 'Horizon Peaks', 6, '#6E7B8B', 'Think ahead: big decisions and long-term plans.'),
  ('kindness-grove', 'Kindness Grove', 7, '#C97C93', 'The joy of giving and helping others with what you have.');
insert into public.activities
  (id, world_id, topic_id, age_band, level, activity_type, title, learning_objective, content, xp_reward, coin_reward_minor_units, order_index)
values
  ('explorer-money_basics-l1', 'coin-cove', 'money_basics', 'explorer', 1, 'lesson', 'What Is Money?', 'Recognise that money is used to get things people want or need.', '{"keyConcept": "Money is something we trade for goods and services instead of swapping items directly.", "vocabulary": [{"term": "money", "definition": "Coins and notes we use to buy things"}, {"term": "trade", "definition": "Swapping one thing for another"}, {"term": "value", "definition": "How much something is worth"}], "explanation": "Money is special paper and metal we use instead of swapping toys directly with someone.", "example": "You give the shop keeper two coins, and you get an apple back.", "interactiveActivity": "Sort a set of pictures into ''Money'' and ''Not Money'' piles.", "gameIdea": "Coin Catch: tap real coin images as they float by, avoid leaf and rock decoys.", "challenge": "Find three things at home that cost money.", "quiz": {"question": "Which of these is money?", "options": ["A coin", "A leaf", "A sticker", "A rock"], "correct_answer": "A coin", "explanation": "Coins are made and used by everyone to buy things — leaves and rocks aren''t."}, "commonMisconception": "Children think any small, round, or shiny object counts as money.", "feedbackMessage": {"success": "Woohoo! You just got better at Money Basics! ⭐", "retry": "Not quite — let''s try the Money Basics quest again together!"}, "masteryCriteria": "Correctly sorts at least 4 of 5 money vs. non-money images.", "childShouldUnderstand": "Money is used to get things we want or need.", "childShouldBeAbleTo": "Visually identify coins and notes.", "financialDecisionSupported": "Recognise real money and not hand over pretend items expecting a purchase to work."}'::jsonb, 15, 5, 1),
  ('explorer-needs_wants-l1', 'market-town', 'needs_wants', 'explorer', 1, 'lesson', 'Need It or Want It?', 'Sort everyday items into needs and wants.', '{"keyConcept": "A need is something you must have to be okay; a want is something nice to have but not essential.", "vocabulary": [{"term": "need", "definition": "Something you must have"}, {"term": "want", "definition": "Something nice to have but not essential"}], "explanation": "Food and a warm coat are needs — a new toy is a want, even if you really, really like it.", "example": "Bread for dinner is a need; a chocolate bar in the shop is a want.", "interactiveActivity": "Drag pictures of items into a ''Need'' bucket or a ''Want'' bucket.", "gameIdea": "Need or Want Sorter: a fast-tap sorting game with a happy sound for correct answers.", "challenge": "Sort ten household items into needs and wants with a grown-up.", "quiz": {"question": "Which of these is a need?", "options": ["A winter coat", "A video game", "A toy car", "Stickers"], "correct_answer": "A winter coat", "explanation": "The correct answer is ‘A winter coat’, based on the concept covered in this activity."}, "commonMisconception": "Children often think anything they really want counts as a need.", "feedbackMessage": {"success": "Woohoo! You just got better at Needs vs Wants! ⭐", "retry": "Not quite — let''s try the Needs vs Wants quest again together!"}, "masteryCriteria": "Correctly sorts at least 8 of 10 items into needs and wants.", "childShouldUnderstand": "Needs and wants are different, even when a want feels really important.", "childShouldBeAbleTo": "Sort a simple item into ''need'' or ''want''.", "financialDecisionSupported": "Pause before asking for something and consider whether it''s really needed."}'::jsonb, 15, 5, 2),
  ('explorer-saving-l1', 'golden-vault', 'saving', 'explorer', 1, 'lesson', 'What Does Saving Mean?', 'Understand that saving means keeping money instead of spending it right away.', '{"keyConcept": "Saving is putting money aside now so you can use it later, often for something bigger.", "vocabulary": [{"term": "save", "definition": "To keep money instead of spending it"}, {"term": "later", "definition": "Not right now, but in the future"}], "explanation": "If you save your coins instead of spending them all, you''ll have more later for something special.", "example": "You save 2 coins a day, and after a week you have 14 coins — enough for a bigger toy.", "interactiveActivity": "Piggy bank animation: add coins each day and watch the pile grow.", "gameIdea": "Growing Piggy Bank: a simple tap-to-save game with a visible growing coin pile.", "challenge": "Save a fictional coin every day for five in-app days without spending it.", "quiz": {"question": "What does ''saving'' money mean?", "options": ["Spending it all today", "Keeping it to use later", "Losing it", "Giving it away"], "correct_answer": "Keeping it to use later", "explanation": "The correct answer is ‘Keeping it to use later’, based on the concept covered in this activity."}, "commonMisconception": "Children think saving means the money disappears or is ''wasted'' by not being spent immediately.", "feedbackMessage": {"success": "Woohoo! You just got better at Saving! ⭐", "retry": "Not quite — let''s try the Saving quest again together!"}, "masteryCriteria": "Successfully saves coins for at least 4 of 5 in-app days without spending them.", "childShouldUnderstand": "Saving means keeping money to use later instead of spending it immediately.", "childShouldBeAbleTo": "Add coins to a saving pile instead of spending them.", "financialDecisionSupported": "Choose to hold onto some money instead of spending it all right away."}'::jsonb, 15, 5, 3);
